#!/usr/bin/env node
// Generates platform token files from tokens/sticker-pop.tokens.json.
// No dependencies: Node 18+ only.
//
//   node tools/build-tokens.mjs           write every platform's files
//   node tools/build-tokens.mjs --check   fail if any generated file is stale
//
// Outputs:
//   packages/flutter/sticker_pop/lib/src/tokens/pop_tokens.g.dart
//   packages/android/stickerpop/src/main/kotlin/dev/stickerpop/tokens/PopTokens.kt
//   packages/ios/StickerPop/Sources/StickerPop/Tokens/PopTokens.swift
//   packages/web/src/tokens.css, packages/web/src/fills.css, packages/web/src/tokens.mjs, packages/web/src/tokens.d.ts
//   tokens/dist/tokens.resolved.json

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const source = JSON.parse(readFileSync(join(root, 'tokens/sticker-pop.tokens.json'), 'utf8'));
const checkOnly = process.argv.includes('--check');

const HEADER = 'GENERATED by tools/build-tokens.mjs from tokens/sticker-pop.tokens.json. Do not edit.';

// ---------------------------------------------------------------------------
// Parse and resolve

/** Flattens a DTCG group into [{ path: ['color','paper'], value, type, description }]. */
function flatten(node, path = [], inheritedType) {
  const out = [];
  const type = node.$type ?? inheritedType;
  for (const [key, child] of Object.entries(node)) {
    if (key.startsWith('$')) continue;
    if (child && typeof child === 'object' && '$value' in child) {
      out.push({ path: [...path, key], value: child.$value, type: child.$type ?? type, description: child.$description });
    } else if (child && typeof child === 'object') {
      out.push(...flatten(child, [...path, key], type));
    }
  }
  return out;
}

const all = flatten(source);
const byPath = new Map(all.map((t) => [t.path.join('.'), t]));

function resolve(value, seen = new Set()) {
  if (typeof value === 'string') {
    const m = value.match(/^\{(.+)\}$/);
    if (m) {
      if (seen.has(m[1])) throw new Error(`Circular reference: ${m[1]}`);
      const target = byPath.get(m[1]);
      if (!target) throw new Error(`Unknown reference: ${value}`);
      return resolve(target.value, new Set([...seen, m[1]]));
    }
  }
  return value;
}

for (const t of all) {
  t.ref = typeof t.value === 'string' && /^\{.+\}$/.test(t.value) ? t.value.slice(1, -1) : null;
  if (t.type === 'gradient') {
    t.stopRefs = t.value.stops.map((s) => (/^\{.+\}$/.test(s.color) ? s.color.slice(1, -1) : null));
    t.value = { angle: t.value.angle, stops: t.value.stops.map((s) => ({ color: resolve(s.color), position: s.position })) };
  } else {
    t.value = resolve(t.value);
  }
}

const group = (name) => all.filter((t) => t.path[0] === name);
const leaf = (t) => t.path.slice(1).join('_').replace(/_([a-z])/g, (_, c) => c.toUpperCase());
const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();

// ---------------------------------------------------------------------------
// Validation: the spec's hard rules, checked at build time.

const errors = [];
const hex = (v) => /^#([0-9a-f]{6}|[0-9a-f]{8})$/i.test(v);
for (const t of group('color')) {
  if (!hex(t.value)) errors.push(`${t.path.join('.')} is not a hex colour: ${t.value}`);
}
for (const t of group('font').filter((t) => t.path[1] === 'weight')) {
  if (t.value < 600) errors.push(`${t.path.join('.')} is lighter than 600`);
}
for (const t of group('text')) {
  if (t.value.weight < 600) errors.push(`${t.path.join('.')} weight is lighter than 600`);
  if (t.value.color && !['ink', 'inkMuted', 'white'].includes(t.value.color)) {
    errors.push(`${t.path.join('.')} uses coloured text (${t.value.color}); text is ink, inkMuted or white on ink`);
  }
}
for (const t of group('tilt')) {
  if (Math.abs(t.value) > 6) errors.push(`${t.path.join('.')} tilts beyond ±6°`);
}
for (const t of group('shadow')) {
  if (t.value < 0) errors.push(`${t.path.join('.')} is negative`);
}

// Gradients: two or more stops, positions 0..1 ascending, angle 0..360.
for (const t of all.filter((t) => t.type === 'gradient')) {
  const { angle, stops } = t.value;
  if (!(angle >= 0 && angle <= 360)) errors.push(`${t.path.join('.')} angle must be 0..360`);
  if (stops.length < 2) errors.push(`${t.path.join('.')} needs at least two stops`);
  stops.forEach((s, i) => {
    if (!hex(s.color)) errors.push(`${t.path.join('.')} stop ${i} is not a colour`);
    if (i > 0 && s.position < stops[i - 1].position) errors.push(`${t.path.join('.')} stops must ascend`);
  });
}

// WCAG contrast of ink on every fill must be ≥ 4.5:1.
function luminance(h) {
  const n = h.slice(1, 7);
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(n.slice(i, i + 2), 16) / 255)
    .map((c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
const contrast = (a, b) => {
  const [l1, l2] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (l1 + 0.05) / (l2 + 0.05);
};
const ink = byPath.get('color.ink').value;
for (const name of ['paper', 'white', 'yellow', 'pink', 'blue', 'mint', 'lilac', 'orange', 'divider']) {
  const c = contrast(ink, byPath.get(`color.${name}`).value);
  if (c < 4.5) errors.push(`ink on ${name} is ${c.toFixed(2)}:1, below 4.5:1`);
}
for (const name of ['paper', 'white']) {
  const c = contrast(byPath.get('color.inkMuted').value, byPath.get(`color.${name}`).value);
  if (c < 4.5) errors.push(`inkMuted on ${name} is ${c.toFixed(2)}:1, below 4.5:1`);
}
for (const t of all.filter((t) => t.type === 'gradient')) {
  t.value.stops.forEach((s, i) => {
    const c = contrast(ink, s.color);
    if (c < 4.5) errors.push(`ink on ${t.path.join('.')} stop ${i} is ${c.toFixed(2)}:1, below 4.5:1`);
  });
}
{
  const c = contrast(byPath.get('color.white').value, ink);
  if (c < 4.5) errors.push(`white on ink is ${c.toFixed(2)}:1, below 4.5:1`);
}

if (errors.length) {
  console.error('Token validation failed:\n  ' + errors.join('\n  '));
  process.exit(1);
}

// ---------------------------------------------------------------------------
// Helpers

/** '#RRGGBB' or '#RRGGBBAA' to an ARGB integer literal: 0xAARRGGBB. */
function argb(h) {
  const n = h.slice(1).toUpperCase();
  const rgb = n.slice(0, 6);
  const a = n.length === 8 ? n.slice(6, 8) : 'FF';
  return `0x${a}${rgb}`;
}
const num = (v) => (Number.isInteger(v) ? `${v}` : `${v}`);
const dbl = (v) => (Number.isInteger(v) ? `${v}.0` : `${v}`);
const doc = (t, indent, prefix = '///') => (t.description ? `${indent}${prefix} ${t.description}\n` : '');
const groupDesc = (name) => source[name]?.$description;

const textTokens = group('text');
const gradientTokens = group('gradient');

/** CSS angle (0 = to top, 90 = to right) to a start/end pair on a -1..1 square. */
function gradientEnds(angle) {
  const rad = (angle * Math.PI) / 180;
  let dx = Math.sin(rad);
  let dy = -Math.cos(rad);
  const k = 1 / Math.max(Math.abs(dx), Math.abs(dy));
  dx = +(dx * k).toFixed(4) + 0;
  dy = +(dy * k).toFixed(4) + 0;
  return { begin: [-dx, -dy], end: [dx, dy] };
}
const colorRef = (t, i) => (t.stopRefs[i]?.startsWith('color.') ? t.stopRefs[i].split('.')[1] : null);

// ---------------------------------------------------------------------------
// Dart (Flutter)

function dart() {
  const L = [];
  L.push(`// ${HEADER}`);
  L.push('// ignore_for_file: public_member_api_docs');
  L.push('');
  L.push("import 'package:flutter/widgets.dart';");
  L.push('');

  const dimClass = (cls, name, desc) => {
    if (desc ?? groupDesc(name)) L.push(`/// ${desc ?? groupDesc(name)}`);
    L.push(`abstract final class ${cls} {`);
    for (const t of group(name)) {
      L.push(doc(t, '  ').trimEnd() || null);
      L.push(`  static const double ${leaf(t)} = ${dbl(t.value)};`);
    }
    L.push('}', '');
  };

  L.push('/// Colour tokens. Text on any bright fill is always [ink].');
  L.push('abstract final class PopColors {');
  for (const t of group('color')) {
    L.push(doc(t, '  ').trimEnd() || null);
    L.push(`  static const Color ${leaf(t)} = Color(${argb(t.value)});`);
  }
  L.push('');
  L.push('  /// The bright fills, in palette order.');
  L.push('  static const List<Color> brights = <Color>[yellow, pink, blue, mint, lilac, orange];');
  L.push('}', '');

  L.push(`/// ${groupDesc('gradient')}`);
  L.push('abstract final class PopGradients {');
  for (const t of gradientTokens) {
    const { begin, end } = gradientEnds(t.value.angle);
    const colors = t.value.stops.map((s, i) => (colorRef(t, i) ? `PopColors.${colorRef(t, i)}` : `Color(${argb(s.color)})`));
    L.push(`  static const LinearGradient ${leaf(t)} = LinearGradient(`);
    L.push(`    begin: Alignment(${dbl(begin[0])}, ${dbl(begin[1])}),`);
    L.push(`    end: Alignment(${dbl(end[0])}, ${dbl(end[1])}),`);
    L.push(`    colors: <Color>[${colors.join(', ')}],`);
    L.push(`    stops: <double>[${t.value.stops.map((s) => dbl(s.position)).join(', ')}],`);
    L.push('  );');
  }
  L.push('');
  L.push('  static const Map<String, LinearGradient> byName = <String, LinearGradient>{');
  for (const t of gradientTokens) L.push(`    '${leaf(t)}': ${leaf(t)},`);
  L.push('  };');
  L.push('}', '');

  L.push('abstract final class PopType {');
  L.push(`  static const String family = '${byPath.get('font.family').value}';`);
  for (const t of group('font').filter((t) => t.path[1] === 'weight')) {
    L.push(`  static const FontWeight ${t.path[2]} = FontWeight.w${t.value};`);
  }
  L.push('}', '');

  L.push('/// One role from the type scale. Turn it into a TextStyle with `popTextOf`.');
  L.push('@immutable');
  L.push('class PopTextSpec {');
  L.push('  const PopTextSpec({');
  L.push('    required this.size,');
  L.push('    required this.weight,');
  L.push('    this.letterSpacing = 0,');
  L.push('    this.height,');
  L.push('    this.tabular = false,');
  L.push('    this.caps = false,');
  L.push('    this.color = PopColors.ink,');
  L.push('  });');
  L.push('');
  L.push('  final double size;');
  L.push('  final FontWeight weight;');
  L.push('  final double letterSpacing;');
  L.push('  final double? height;');
  L.push('  final bool tabular;');
  L.push('');
  L.push('  /// Set the text in ALL CAPS (section labels and badges only).');
  L.push('  final bool caps;');
  L.push('  final Color color;');
  L.push('}', '');

  L.push(`/// The type scale. ${groupDesc('text')}`);
  L.push('abstract final class PopTextSpecs {');
  for (const t of textTokens) {
    const v = t.value;
    const args = [`size: ${dbl(v.size)}`, `weight: FontWeight.w${v.weight}`];
    if (v.letterSpacing) args.push(`letterSpacing: ${dbl(v.letterSpacing)}`);
    if (v.lineHeight) args.push(`height: ${dbl(v.lineHeight)}`);
    if (v.tabular) args.push('tabular: true');
    if (v.caps) args.push('caps: true');
    if (v.color) args.push(`color: PopColors.${v.color}`);
    L.push(doc(t, '  ').trimEnd() || null);
    L.push(`  static const PopTextSpec ${leaf(t)} = PopTextSpec(${args.join(', ')});`);
  }
  L.push('}', '');

  dimClass('PopSpace', 'space');
  dimClass('PopBorder', 'border');
  dimClass('PopRadius', 'radius');

  L.push(`/// ${groupDesc('shadow')}`);
  L.push('abstract final class PopShadow {');
  for (const t of group('shadow')) {
    L.push(doc(t, '  ').trimEnd() || null);
    L.push(`  static const Offset ${leaf(t)} = Offset(${dbl(t.value)}, ${dbl(t.value)});`);
  }
  L.push('}', '');

  dimClass('PopTilt', 'tilt');
  dimClass('PopSize', 'size');

  L.push('abstract final class PopMotion {');
  for (const t of group('motion')) {
    L.push(`  static const Duration ${leaf(t)} = Duration(milliseconds: ${t.value});`);
  }
  L.push('}', '');

  dimClass('PopOpacity', 'opacity');

  L.push('/// Short aliases for the most used shape tokens.');
  L.push('abstract final class PopShape {');
  L.push('  static const double border = PopBorder.regular;');
  L.push('  static const double borderThin = PopBorder.thin;');
  L.push('  static const double radiusCard = PopRadius.card;');
  L.push('  static const double radiusTile = PopRadius.tile;');
  L.push('  static const double radiusPill = PopRadius.pill;');
  L.push('  static const Offset shadowSmall = PopShadow.small;');
  L.push('  static const Offset shadow = PopShadow.regular;');
  L.push('  static const Offset shadowLarge = PopShadow.large;');
  L.push('}', '');

  return L.filter((l) => l !== null).join('\n');
}

// ---------------------------------------------------------------------------
// Kotlin (Jetpack Compose)

function kotlin() {
  const L = [];
  L.push(`// ${HEADER}`);
  L.push('package dev.stickerpop.tokens', '');
  L.push('import androidx.compose.ui.geometry.Offset');
  L.push('import androidx.compose.ui.geometry.Size');
  L.push('import androidx.compose.ui.graphics.Brush');
  L.push('import androidx.compose.ui.graphics.Color');
  L.push('import androidx.compose.ui.graphics.LinearGradientShader');
  L.push('import androidx.compose.ui.graphics.Shader');
  L.push('import androidx.compose.ui.graphics.ShaderBrush');
  L.push('import androidx.compose.ui.text.font.FontWeight');
  L.push('import androidx.compose.ui.unit.Dp');
  L.push('import androidx.compose.ui.unit.TextUnit');
  L.push('import androidx.compose.ui.unit.dp');
  L.push('import androidx.compose.ui.unit.sp');
  L.push('import kotlin.math.abs');
  L.push('import kotlin.math.cos');
  L.push('import kotlin.math.sin', '');

  const kdoc = (t, i) => (t.description ? `${i}/** ${t.description} */` : null);
  const dpObj = (obj, name) => {
    if (groupDesc(name)) L.push(`/** ${groupDesc(name)} */`);
    L.push(`object ${obj} {`);
    for (const t of group(name)) {
      L.push(kdoc(t, '    '));
      L.push(`    val ${leaf(t)}: Dp = ${num(t.value)}.dp`);
    }
    L.push('}', '');
  };
  const floatObj = (obj, name) => {
    if (groupDesc(name)) L.push(`/** ${groupDesc(name)} */`);
    L.push(`object ${obj} {`);
    for (const t of group(name)) {
      L.push(kdoc(t, '    '));
      L.push(`    const val ${leaf(t)}: Float = ${dbl(t.value)}f`);
    }
    L.push('}', '');
  };

  L.push('/** Colour tokens. Text on any bright fill is always [ink]. */');
  L.push('object PopColors {');
  for (const t of group('color')) {
    L.push(kdoc(t, '    '));
    L.push(`    val ${leaf(t)} = Color(${argb(t.value)})`);
  }
  L.push('    val brights: List<Color> = listOf(yellow, pink, blue, mint, lilac, orange)');
  L.push('}', '');

  L.push('/** A linear gradient from the tokens. Use [brush] to paint with it. */');
  L.push('data class PopGradient(val colors: List<Color>, val stops: List<Float>, val angleDegrees: Float) {');
  L.push('    /** A brush that runs at [angleDegrees] (CSS-style: 0 = to top, 90 = to right) across whatever it fills. */');
  L.push('    val brush: Brush = object : ShaderBrush() {');
  L.push('        override fun createShader(size: Size): Shader {');
  L.push('            val rad = Math.toRadians(angleDegrees.toDouble())');
  L.push('            var dx = sin(rad).toFloat()');
  L.push('            var dy = -cos(rad).toFloat()');
  L.push('            val k = 1f / maxOf(abs(dx), abs(dy))');
  L.push('            dx *= k; dy *= k');
  L.push('            val c = Offset(size.width / 2, size.height / 2)');
  L.push('            val start = Offset(c.x - dx * size.width / 2, c.y - dy * size.height / 2)');
  L.push('            val end = Offset(c.x + dx * size.width / 2, c.y + dy * size.height / 2)');
  L.push('            return LinearGradientShader(start, end, colors, stops)');
  L.push('        }');
  L.push('    }');
  L.push('}', '');
  L.push(`/** ${groupDesc('gradient')} */`);
  L.push('object PopGradients {');
  for (const t of gradientTokens) {
    const colors = t.value.stops.map((s, i) => (colorRef(t, i) ? `PopColors.${colorRef(t, i)}` : `Color(${argb(s.color)})`));
    L.push(`    val ${leaf(t)} = PopGradient(listOf(${colors.join(', ')}), listOf(${t.value.stops.map((s) => `${dbl(s.position)}f`).join(', ')}), ${dbl(t.value.angle)}f)`);
  }
  L.push(`    val byName: Map<String, PopGradient> = mapOf(${gradientTokens.map((t) => `"${leaf(t)}" to ${leaf(t)}`).join(', ')})`);
  L.push('}', '');

  L.push('object PopType {');
  L.push(`    const val family: String = "${byPath.get('font.family').value}"`);
  for (const t of group('font').filter((t) => t.path[1] === 'weight')) {
    L.push(`    val ${t.path[2]}: FontWeight = FontWeight(${t.value})`);
  }
  L.push('}', '');

  L.push('/** One role from the type scale. Turn it into a TextStyle with `popTextStyle`. */');
  L.push('data class PopTextSpec(');
  L.push('    val size: TextUnit,');
  L.push('    val weight: FontWeight,');
  L.push('    val letterSpacing: TextUnit = 0.sp,');
  L.push('    val lineHeight: Float? = null,');
  L.push('    val tabular: Boolean = false,');
  L.push('    val caps: Boolean = false,');
  L.push('    val color: Color = PopColors.ink,');
  L.push(')', '');

  L.push(`/** The type scale. ${groupDesc('text')} */`);
  L.push('object PopTextSpecs {');
  for (const t of textTokens) {
    const v = t.value;
    const args = [`size = ${num(v.size)}.sp`, `weight = FontWeight(${v.weight})`];
    if (v.letterSpacing) args.push(`letterSpacing = (${num(v.letterSpacing)}).sp`);
    if (v.lineHeight) args.push(`lineHeight = ${dbl(v.lineHeight)}f`);
    if (v.tabular) args.push('tabular = true');
    if (v.caps) args.push('caps = true');
    if (v.color) args.push(`color = PopColors.${v.color}`);
    L.push(kdoc(t, '    '));
    L.push(`    val ${leaf(t)} = PopTextSpec(${args.join(', ')})`);
  }
  L.push('}', '');

  dpObj('PopSpace', 'space');
  dpObj('PopBorder', 'border');
  dpObj('PopRadius', 'radius');
  dpObj('PopShadow', 'shadow');
  floatObj('PopTilt', 'tilt');
  const sizes = group('size').filter((t) => t.type !== 'number');
  L.push('object PopSize {');
  for (const t of sizes) L.push(`    val ${leaf(t)}: Dp = ${num(t.value)}.dp`);
  for (const t of group('size').filter((t) => t.type === 'number')) {
    L.push(`    const val ${leaf(t)}: Float = ${dbl(t.value)}f`);
  }
  L.push('}', '');
  L.push('object PopMotion {');
  for (const t of group('motion')) L.push(`    const val ${leaf(t)}Millis: Int = ${t.value}`);
  L.push('}', '');
  floatObj('PopOpacity', 'opacity');

  return L.filter((l) => l !== null).join('\n');
}

// ---------------------------------------------------------------------------
// Swift (SwiftUI)

function swift() {
  const L = [];
  L.push(`// ${HEADER}`, '');
  L.push('import SwiftUI', '');

  const sdoc = (t, i) => (t.description ? `${i}/// ${t.description}` : null);
  const cgEnum = (en, name) => {
    if (groupDesc(name)) L.push(`/// ${groupDesc(name)}`);
    L.push(`public enum ${en} {`);
    for (const t of group(name)) {
      L.push(sdoc(t, '    '));
      L.push(`    public static let ${leaf(t)}: CGFloat = ${dbl(t.value)}`);
    }
    L.push('}', '');
  };

  L.push('extension Color {');
  L.push('    /// An sRGB colour from 0xRRGGBB, with optional opacity.');
  L.push('    init(popHex hex: UInt32, opacity: Double = 1) {');
  L.push('        self.init(.sRGB,');
  L.push('                  red: Double((hex >> 16) & 0xFF) / 255,');
  L.push('                  green: Double((hex >> 8) & 0xFF) / 255,');
  L.push('                  blue: Double(hex & 0xFF) / 255,');
  L.push('                  opacity: opacity)');
  L.push('    }');
  L.push('}', '');

  L.push('/// Colour tokens. Text on any bright fill is always `ink`.');
  L.push('public enum PopColors {');
  for (const t of group('color')) {
    const n = t.value.slice(1).toUpperCase();
    const op = n.length === 8 ? `, opacity: ${(parseInt(n.slice(6), 16) / 255).toFixed(2)}` : '';
    L.push(sdoc(t, '    '));
    L.push(`    public static let ${leaf(t)} = Color(popHex: 0x${n.slice(0, 6)}${op})`);
  }
  L.push('    public static let brights: [Color] = [yellow, pink, blue, mint, lilac, orange]');
  L.push('}', '');

  L.push(`/// ${groupDesc('gradient')}`);
  L.push('public enum PopGradients {');
  for (const t of gradientTokens) {
    const { begin, end } = gradientEnds(t.value.angle);
    const u = ([x, y]) => `UnitPoint(x: ${dbl(+(0.5 + x / 2).toFixed(4))}, y: ${dbl(+(0.5 + y / 2).toFixed(4))})`;
    const stops = t.value.stops.map((s, i) => `.init(color: ${colorRef(t, i) ? `PopColors.${colorRef(t, i)}` : `Color(popHex: 0x${s.color.slice(1, 7)})`}, location: ${dbl(s.position)})`);
    L.push(`    public static let ${leaf(t)} = LinearGradient(stops: [${stops.join(', ')}], startPoint: ${u(begin)}, endPoint: ${u(end)})`);
  }
  L.push(`    public static let byName: [String: LinearGradient] = [${gradientTokens.map((t) => `"${leaf(t)}": ${leaf(t)}`).join(', ')}]`);
  L.push('}', '');

  L.push('public enum PopType {');
  L.push(`    public static let family = "${byPath.get('font.family').value}"`);
  for (const t of group('font').filter((t) => t.path[1] === 'weight')) {
    L.push(`    public static let ${t.path[2]}: CGFloat = ${t.value}`);
  }
  L.push('}', '');

  L.push('/// One role from the type scale. Apply it with `.popText(_:)`.');
  L.push('public struct PopTextSpec: Sendable {');
  L.push('    public let size: CGFloat');
  L.push('    public let weight: CGFloat');
  L.push('    public var letterSpacing: CGFloat');
  L.push('    public var lineHeight: CGFloat?');
  L.push('    public var tabular: Bool');
  L.push('    public var caps: Bool');
  L.push('    public var color: PopTextColor');
  L.push('');
  L.push('    public init(size: CGFloat, weight: CGFloat, letterSpacing: CGFloat = 0, lineHeight: CGFloat? = nil,');
  L.push('                tabular: Bool = false, caps: Bool = false, color: PopTextColor = .ink) {');
  L.push('        self.size = size');
  L.push('        self.weight = weight');
  L.push('        self.letterSpacing = letterSpacing');
  L.push('        self.lineHeight = lineHeight');
  L.push('        self.tabular = tabular');
  L.push('        self.caps = caps');
  L.push('        self.color = color');
  L.push('    }');
  L.push('}', '');
  L.push('public enum PopTextColor: Sendable { case ink, inkMuted, white }', '');

  L.push(`/// The type scale. ${groupDesc('text')}`);
  L.push('public enum PopTextSpecs {');
  for (const t of textTokens) {
    const v = t.value;
    const args = [`size: ${dbl(v.size)}`, `weight: ${v.weight}`];
    if (v.letterSpacing) args.push(`letterSpacing: ${dbl(v.letterSpacing)}`);
    if (v.lineHeight) args.push(`lineHeight: ${dbl(v.lineHeight)}`);
    if (v.tabular) args.push('tabular: true');
    if (v.caps) args.push('caps: true');
    if (v.color) args.push(`color: .${v.color}`);
    L.push(sdoc(t, '    '));
    L.push(`    public static let ${leaf(t)} = PopTextSpec(${args.join(', ')})`);
  }
  L.push('}', '');

  cgEnum('PopSpace', 'space');
  cgEnum('PopBorder', 'border');
  cgEnum('PopRadius', 'radius');
  cgEnum('PopShadow', 'shadow');
  cgEnum('PopTilt', 'tilt');
  cgEnum('PopSize', 'size');
  L.push('public enum PopMotion {');
  for (const t of group('motion')) L.push(`    public static let ${leaf(t)}: Double = ${t.value / 1000}`);
  L.push('}', '');
  cgEnum('PopOpacity', 'opacity');

  return L.filter((l) => l !== null).join('\n');
}

// ---------------------------------------------------------------------------
// Web: CSS custom properties, text utility classes, ES module + types

const unitFor = (t) => {
  if (t.type === 'dimension') return `${t.value}px`;
  if (t.type === 'duration') return `${t.value}ms`;
  if (t.type === 'number' && t.path[0] === 'tilt') return `${t.value}deg`;
  return `${t.value}`;
};

function css() {
  const L = [`/* ${HEADER} */`, '', ':root {'];
  for (const t of group('color')) {
    L.push(`  --sp-${t.path[0]}-${kebab(leaf(t))}: ${t.ref ? `var(--sp-${t.ref.split('.').map(kebab).join('-')})` : t.value.toLowerCase()};`);
  }
  for (const t of gradientTokens) {
    const stops = t.value.stops.map((s, i) => `${colorRef(t, i) ? `var(--sp-color-${kebab(colorRef(t, i))})` : s.color} ${+(s.position * 100).toFixed(2)}%`);
    L.push(`  --sp-gradient-${kebab(leaf(t))}: linear-gradient(${t.value.angle}deg, ${stops.join(', ')});`);
  }
  L.push(`  --sp-font-family: 'Bricolage Grotesque', 'BricolageGrotesque', system-ui, sans-serif;`);
  for (const t of group('font').filter((t) => t.path[1] === 'weight')) L.push(`  --sp-font-weight-${t.path[2]}: ${t.value};`);
  for (const name of ['space', 'border', 'radius', 'shadow', 'tilt', 'size', 'motion', 'opacity']) {
    for (const t of group(name)) {
      const value = t.ref ? `var(--sp-${t.ref.split('.').map(kebab).join('-')})` : unitFor(t);
      L.push(`  --sp-${name}-${kebab(leaf(t))}: ${value};`);
    }
  }
  L.push('}', '');
  for (const t of textTokens) {
    const v = t.value;
    L.push(`.sp-text-${kebab(leaf(t))} {`);
    L.push('  font-family: var(--sp-font-family);');
    L.push(`  font-size: ${v.size}px;`);
    L.push(`  font-weight: ${v.weight};`);
    L.push(`  font-variation-settings: 'wght' ${v.weight};`);
    if (v.letterSpacing) L.push(`  letter-spacing: ${v.letterSpacing}px;`);
    if (v.lineHeight) L.push(`  line-height: ${v.lineHeight};`);
    if (v.tabular) L.push('  font-variant-numeric: tabular-nums;\n  white-space: nowrap;');
    if (v.caps) L.push('  text-transform: uppercase;');
    L.push(`  color: var(--sp-color-${kebab(v.color ?? 'ink')});`);
    L.push('}');
  }
  return L.join('\n') + '\n';
}

// Fill utilities live in their own file, loaded after components.css, so a
// fill class always beats a component's default background (same specificity,
// later in the cascade).
const FILL_COLORS = ['white', 'paper', 'yellow', 'pink', 'blue', 'mint', 'lilac', 'orange'];
function fillsCss() {
  const L = [`/* ${HEADER} */`, '', '/* Fills: load after components.css (sticker-pop.css does this). */'];
  for (const c of FILL_COLORS) L.push(`.sp-fill-${kebab(c)} { background: var(--sp-color-${kebab(c)}); }`);
  for (const t of gradientTokens) L.push(`.sp-fill-${kebab(leaf(t))} { background: var(--sp-gradient-${kebab(leaf(t))}); }`);
  return L.join('\n') + '\n';
}

function resolvedTree() {
  const out = {};
  for (const t of all) {
    let node = out;
    for (const p of t.path.slice(0, -1)) node = node[p] ??= {};
    node[t.path.at(-1)] = t.value;
  }
  return out;
}

function esm() {
  return `// ${HEADER}\n\nexport const tokens = ${JSON.stringify(resolvedTree(), null, 2)};\n\nexport default tokens;\n`;
}

function dts() {
  const tree = resolvedTree();
  const typeOf = (v, i) => {
    if (v && typeof v === 'object') {
      const pad = '  '.repeat(i + 1);
      return `{\n${Object.entries(v).map(([k, c]) => `${pad}readonly ${k}: ${typeOf(c, i + 1)};`).join('\n')}\n${'  '.repeat(i)}}`;
    }
    return typeof v === 'string' ? JSON.stringify(v) : `${v}`;
  };
  return `// ${HEADER}\n\nexport declare const tokens: ${typeOf(tree, 0)};\n\nexport default tokens;\n`;
}

// ---------------------------------------------------------------------------
// Write or check

const outputs = {
  'packages/flutter/sticker_pop/lib/src/tokens/pop_tokens.g.dart': dart(),
  'packages/android/stickerpop/src/main/kotlin/dev/stickerpop/tokens/PopTokens.kt': kotlin(),
  'packages/ios/StickerPop/Sources/StickerPop/Tokens/PopTokens.swift': swift(),
  'packages/web/src/tokens.css': css(),
  'packages/web/src/fills.css': fillsCss(),
  'packages/web/src/tokens.mjs': esm(),
  'packages/web/src/tokens.d.ts': dts(),
  'tokens/dist/tokens.resolved.json': JSON.stringify(resolvedTree(), null, 2) + '\n',
};

let stale = 0;
for (const [rel, content] of Object.entries(outputs)) {
  const file = join(root, rel);
  const body = content.endsWith('\n') ? content : content + '\n';
  if (checkOnly) {
    if (!existsSync(file) || readFileSync(file, 'utf8') !== body) {
      console.error(`stale: ${rel}`);
      stale++;
    }
    continue;
  }
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, body);
  console.log(`wrote ${relative(root, file)}`);
}
if (checkOnly) {
  if (stale) {
    console.error(`${stale} generated file(s) are out of date. Run: node tools/build-tokens.mjs`);
    process.exit(1);
  }
  console.log('Generated tokens are up to date.');
}
